{{- if .Values.rbac.create -}}
{{- $serviceName := include "meltano-catalog.fullname" . -}}

{{- if and .Values.appService.dataflowTasksNamespace (ne .Values.appService.dataflowTasksNamespace .Release.Namespace) }}
apiVersion: v1
kind: Namespace
metadata:
  name: {{ .Values.appService.dataflowTasksNamespace }}
---
{{- end }}

# This role is used to allow Matatika Catalog to read configuration from config maps via Kubernetes plugin.
apiVersion: rbac.authorization.k8s.io/v1
kind: Role
metadata:
  name: {{ $serviceName }}-dataflow-config
  namespace: {{ .Release.Namespace }}
  labels:
    app.kubernetes.io/name: {{ include "meltano-catalog.name" . }}-dataflow-config
    helm.sh/chart: "{{ .Chart.Name }}-{{ .Chart.Version }}"
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
    chart: "{{ .Chart.Name }}-{{ .Chart.Version | replace "+" "_" }}"
  annotations:
    checksum/values: {{ (print $.Values) | sha256sum }}
rules:
  - apiGroups: ["", "extensions", "apps"]
    resources: ["configmaps"]
    verbs: ["get", "list", "watch"]

---

# We bind the role to the service account, in the namespace where the Catalog is released.
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata:
  name: {{ $serviceName }}-dataflow-config
  namespace: {{ .Release.Namespace }}
  labels:
    app.kubernetes.io/name: {{ include "meltano-catalog.name" . }}-dataflow-config
    helm.sh/chart: "{{ .Chart.Name }}-{{ .Chart.Version }}"
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
    chart: "{{ .Chart.Name }}-{{ .Chart.Version | replace "+" "_" }}"
  annotations:
    checksum/values: {{ (print $.Values) | sha256sum }}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: Role
  name: {{ $serviceName }}-dataflow-config
subjects:
- kind: ServiceAccount
  name: {{ .Values.appService.dataflowTasksServiceAccountName }}
  namespace: {{ .Release.Namespace }}
{{- /*
  When gcp.enabled is set, the chart's serviceaccount.yaml provisions a
  dedicated KSA for Workload Identity (gcp.serviceAccountName) and the
  deployment.yaml runs the catalog pod as that KSA instead of `default`.
  Add it as an explicit subject so the actual pod principal matches this
  binding. No-op when gcp.enabled is false (AWS/Azure path), so this is
  safe across all clouds.
*/}}
{{- if and .Values.gcp.enabled (ne .Values.gcp.serviceAccountName .Values.appService.dataflowTasksServiceAccountName) }}
- kind: ServiceAccount
  name: {{ .Values.gcp.serviceAccountName }}
  namespace: {{ .Release.Namespace }}
{{- end }}

---

# This role is used to allow Matatika Catalog to run DataFlow tasks via Kubernetes plugin.
apiVersion: rbac.authorization.k8s.io/v1
kind: Role
metadata:
  name: {{ $serviceName }}-dataflow-tasks
  namespace: {{ .Values.appService.dataflowTasksNamespace }}
  labels:
    app.kubernetes.io/name: {{ include "meltano-catalog.name" . }}-dataflow-tasks
    helm.sh/chart: "{{ .Chart.Name }}-{{ .Chart.Version }}"
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
    chart: "{{ .Chart.Name }}-{{ .Chart.Version | replace "+" "_" }}"
  annotations:
    checksum/values: {{ (print $.Values) | sha256sum }}
rules:
  - apiGroups: [""]
    resources: ["pods", "pods/exec", "pods/log", "persistentvolumeclaims"]
    verbs: ["get", "list", "watch", "create", "delete", "deletecollection", "patch", "update"]

---

# We bind the role to the service account. The role binding is created in the namespace
# where the dataflow tasks are run.
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata:
  name: {{ $serviceName }}-dataflow-tasks
  namespace: {{ .Values.appService.dataflowTasksNamespace }}
  labels:
    app.kubernetes.io/name: {{ include "meltano-catalog.name" . }}-dataflow-tasks
    helm.sh/chart: "{{ .Chart.Name }}-{{ .Chart.Version }}"
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
    chart: "{{ .Chart.Name }}-{{ .Chart.Version | replace "+" "_" }}"
  annotations:
    checksum/values: {{ (print $.Values) | sha256sum }}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: Role
  name: {{ $serviceName }}-dataflow-tasks
subjects:
- kind: ServiceAccount
  name: {{ .Values.appService.dataflowTasksServiceAccountName }}
  namespace: {{ .Values.appService.dataflowTasksNamespace }}
- kind: ServiceAccount
  name: {{ .Values.appService.dataflowTasksServiceAccountName }}
  namespace: {{ .Release.Namespace }}
{{- /*
  See comment on the dataflow-config RoleBinding above. The catalog pod is
  the principal that talks to the tasks namespace (creates the workspace
  pod, polls its status, etc.), so its actual KSA must be a subject here
  too. No-op when gcp.enabled is false.
*/}}
{{- if and .Values.gcp.enabled (ne .Values.gcp.serviceAccountName .Values.appService.dataflowTasksServiceAccountName) }}
- kind: ServiceAccount
  name: {{ .Values.gcp.serviceAccountName }}
  namespace: {{ .Release.Namespace }}
{{- end }}

{{- end }}

{{- if and (eq .Values.persistence.storageClass "custom") (not .Values.persistence.existingClaim) }}
kind: StorageClass
apiVersion: storage.k8s.io/v1
metadata:
  name: {{ include "matatika-www.fullname" . }}-{{ .Values.persistence.storageClass }}
provisioner: file.csi.azure.com
mountOptions:
  - dir_mode=0777
  - file_mode=0644
  - uid=1001
  - gid=33
  - mfsymlinks
  - cache=strict
parameters:
  skuName: Standard_LRS
  storageAccount: {{ .Values.persistence.storageAccount }}
  {{- if .Values.persistence.shareName }}
  shareName: {{ .Values.persistence.shareName }}
  {{- end }}
  {{- if .Values.persistence.storageAccountKey }}
  secretName: {{ .Release.Name }}-azurefile
  {{- end }}
  resourceGroup: {{ .Values.persistence.resourceGroup }}
reclaimPolicy: Retain
{{- end }}

{{- if .Values.podMonitoring.enabled }}
apiVersion: monitoring.googleapis.com/v1
kind: PodMonitoring
metadata:
  name: {{ include "meltano-catalog.fullname" . }}-jvm
  labels:
    app.kubernetes.io/name: {{ include "meltano-catalog.name" . }}
    helm.sh/chart: {{ include "meltano-catalog.chart" . }}
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
spec:
  selector:
    matchLabels:
      app: {{ include "meltano-catalog.fullname" . }}-app
  endpoints:
  - port: metrics
    path: /metrics
    interval: {{ .Values.podMonitoring.interval }}
  targetLabels:
    metadata:
    - pod
    - container
{{- end }}

apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ template "mysql.fullname" . }}-test
  labels:
    app: {{ template "mysql.fullname" . }}
    chart: "{{ .Chart.Name }}-{{ .Chart.Version }}"
    heritage: "{{ .Release.Service }}"
    release: "{{ .Release.Name }}"
data:
  run.sh: |-
    {{- if .Values.ssl.enabled | and .Values.mysqlRootPassword }}
    @test "Testing SSL MySQL Connection" {
      mysql --host={{ template "mysql.fullname" . }} --port={{ .Values.service.port | default "3306" }} --ssl-cert=/ssl/server-cert.pem --ssl-key=ssl/server-key.pem -u root -p{{ .Values.mysqlRootPassword }}
    }
    {{- else if .Values.mysqlRootPassword }}
    @test "Testing MySQL Connection" {
      mysql --host={{ template "mysql.fullname" . }} --port={{ .Values.service.port | default "3306" }} -u root -p{{ .Values.mysqlRootPassword }}
    }
    {{- end }}

resource "kubernetes_namespace" "prometheus" {
  count = var.deploy_prometheus ? 1 : 0
  metadata {
    annotations = {
      name = "prometheus"
    }

    name = "prometheus"
  }
}

resource "helm_release" "prometheus" {
  count      = var.deploy_prometheus ? 1 : 0
  name       = "prometheus"
  repository = "https://prometheus-community.github.io/helm-charts"
  chart      = "kube-prometheus-stack"
  namespace  = kubernetes_namespace.prometheus[0].metadata[0].name
  version    = "82.10.5"
}

